def money(value: Any) -> Decimal | None:
    """Parse a monetary value to cents, or return ``None`` if it is not money."""
    try:
        return Decimal(str(value)).quantize(Decimal("0.01"))
    except (InvalidOperation, TypeError, ValueError):
        return None


def rows(state: Mapping[str, Any] | None, key: str) -> list[dict[str, Any]]:
    """Return one collection of a state document as a list of records."""
    if not isinstance(state, Mapping):
        return []
    value = state.get(key)
    if isinstance(value, list):
        return [dict(item) for item in value if isinstance(item, Mapping)]
    if isinstance(value, Mapping):
        return [dict(value)]
    return []


def unique(records: Sequence[Mapping[str, Any]], **fields: Any) -> tuple[dict[str, Any] | None, int]:
    """Return the single record matching every field, and how many matched.

    The count is returned alongside the record so a caller can distinguish
    "absent" from "duplicated"; the latter is a real failure mode, because a
    step that ran twice produces two records where one was asked for.
    """
    found = [
        dict(record)
        for record in records
        if all(record.get(key) == value for key, value in fields.items())
    ]
    return (found[0] if len(found) == 1 else None), len(found)


def matches(record: Mapping[str, Any] | None, expected: Mapping[str, Any]) -> bool:
    """Whether every field the expectation names holds exactly the stated value."""
    if not isinstance(record, Mapping):
        return False
    for key, value in expected.items():
        actual = record.get(key)
        if key == 'amount' or isinstance(value, Decimal):
            if money(value) is None or money(actual) != money(value):
                return False
        elif isinstance(value, list):
            if not isinstance(actual, list) or list(actual) != list(value):
                return False
        else:
            if actual != value:
                return False
    return True


def canonical(value: Any) -> bytes:
    """Serialize a value the way the ruleset digest is computed over it."""
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def record(
    name: str,
    passed: bool,
    expected: Any = None,
    observed: Any = None,
    *,
    steps: Sequence[int] = (),
    evidence: Any = None,
) -> dict[str, Any]:
    """Build one check record in the shape the recorded runs carry."""
    return {
        "name": f"{name}_exact",
        "steps": list(steps),
        "passed": bool(passed),
        "expected": json_safe(expected),
        "observed": json_safe(observed),
        "evidence": json_safe(evidence),
        "failure_reason": None
        if passed
        else "exact value, shape, cardinality, or causal-event mismatch",
    }


def json_safe(value: Any) -> Any:
    """Convert a value into something a JSON writer accepts."""
    if isinstance(value, Decimal):
        return format(value, "f")
    if isinstance(value, Mapping):
        return {str(key): json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_safe(item) for item in value]
    return value


